"use client";
import {useEffect,useMemo,useState} from "react";
import {ArrowLeft,Check,CheckCircle2,ChevronRight,CircleAlert,CloudCog,Copy,Database,ExternalLink,FileSpreadsheet,Globe2,KeyRound,Link2,Play,Plus,RefreshCw,Save,Search,ShieldCheck,Sparkles,Trash2,Webhook,X,Zap} from "lucide-react";
import {api,connectorApi,type ApiConfig,type Connector} from "@/lib/api-client";
import {notify} from "@/lib/notifications";

type Props={config:ApiConfig;onClose:()=>void;onOpenProject?:(projectId:string)=>void};
const entities=["project","task","resource"] as const;
const fieldHints:any={project:["externalId","name","description","startDate"],task:["externalId","name","description","expectedStart","expectedEnd","status","progressPct","resourceExternalId"],resource:["externalId","name","role","capacityHoursPerDay"]};
const providerMeta:any={
  "google-sheets":{label:"Google Sheets",sub:"Browse spreadsheets, preview rows and map columns",icon:FileSpreadsheet,accent:"google"},
  "microsoft-365":{label:"Microsoft 365 / Excel",sub:"Connect Microsoft Graph and workbooks",icon:CloudCog,accent:"microsoft"},
  "prms":{label:"PRMS",sub:"Secure token exchange, then access PRMS APIs",icon:Link2,accent:"api"},
  "generic-rest":{label:"REST / OpenAPI",sub:"Import an API contract or discover endpoints",icon:Globe2,accent:"api"},
  proprietary:{label:"Proprietary API",sub:"Guided connection for internal systems",icon:Zap,accent:"api"}
};

export function ConnectorHub({config,onClose,onOpenProject}:Props){
 const [items,setItems]=useState<Connector[]>([]),[selected,setSelected]=useState<Connector|null>(null),[showNew,setShowNew]=useState(false),[busy,setBusy]=useState(false),[tab,setTab]=useState("overview");
 const load=async()=>{try{setItems(await connectorApi.list(config))}catch(e){notify({kind:"error",title:"Unable to load connectors",message:e instanceof Error?e.message:"The connector service could not be reached."})}};
 useEffect(()=>{void load()},[]);
 async function open(c:Connector){setSelected(await connectorApi.get(config,c.id));setTab(c.provider==="google-sheets"?"data":"overview");}
 async function test(id:string){setBusy(true);try{const r=await connectorApi.test(config,id);notify({kind:"success",title:"Connection validated",message:`The external application responded successfully. ${Array.isArray(r.sample)?`${r.sample.length} sample records loaded.`:"A response was received."}`});await load();setSelected(await connectorApi.get(config,id))}catch(e){notify({kind:"error",title:"Connection test failed",message:e instanceof Error?e.message:"The connector test failed."})}finally{setBusy(false)}}
 async function sync(id:string){setBusy(true);try{const r=await connectorApi.sync(config,id);notify({kind:"success",title:"Synchronization completed",message:`Read ${r.recordsRead}, created ${r.recordsCreated}, updated ${r.recordsUpdated}, failed ${r.recordsFailed}.`});await load();setSelected(await connectorApi.get(config,id))}catch(e){notify({kind:"error",title:"Synchronization failed",message:e instanceof Error?e.message:"The synchronization failed. No partial UI state was committed."})}finally{setBusy(false)}}
 async function remove(id:string){if(!confirm("Delete this connector and its mappings, identities and sync history?"))return;try{await connectorApi.remove(config,id);notify({kind:"success",title:"Connection removed",message:"The external connection and its local integration metadata were removed."});setSelected(null);await load()}catch{}}
 if(selected)return <ConnectorDetail config={config} connector={selected} onBack={()=>{setSelected(null);void load()}} onRefresh={async()=>setSelected(await connectorApi.get(config,selected.id))} onTest={()=>test(selected.id)} onSync={()=>sync(selected.id)} busy={busy} onDelete={()=>remove(selected.id)} tab={tab} setTab={setTab} onOpenProject={onOpenProject}/>;
 return <section className="connector-hub connector-studio"><header className="connector-hero"><div><span className="eyebrow">CONNECTOR STUDIO · CONTROL PLANE</span><h1>Connect anything. Understand everything.</h1><p>Connect an account, discover the data, map the fields, validate the contract, then let Schedule Intelligence synchronize only what you authorize.</p></div><button className="primary-button" onClick={()=>setShowNew(true)}><Plus size={15}/> Connect application</button></header>
  <div className="connector-principles"><span><ShieldCheck size={14}/> Encrypted credentials</span><span><Sparkles size={14}/> Discover before mapping</span><span><Link2 size={14}/> Read / write independently</span><span><Webhook size={14}/> Polling + webhooks</span><span><CheckCircle2 size={14}/> Every action validated</span></div>
  <div className="connector-studio-intro"><div><b>One integration model, two experiences.</b><span>First-class apps hide API plumbing. Universal APIs expose a guided contract builder when you need control.</span></div><div className="studio-flow"><i>Connect</i><ChevronRight/><i>Discover</i><ChevronRight/><i>Map</i><ChevronRight/><i>Validate</i><ChevronRight/><i>Sync</i></div></div>
  {items.length===0?<div className="connector-empty connector-empty-hero"><div className="connector-empty-orb"><Link2 size={25}/></div><h2>Your integration control plane is empty</h2><p>Start with Google Sheets for a visual spreadsheet flow, or use REST / OpenAPI for a proprietary application.</p><button className="primary-button" onClick={()=>setShowNew(true)}><Plus size={15}/> Build your first connection</button></div>:<div className="connector-grid">{items.map(c=>{const m=providerMeta[c.provider]||providerMeta["generic-rest"];const Icon=m.icon;return <button key={c.id} className="connector-card connector-card-v2" onClick={()=>void open(c)}><div className="connector-card-top"><span className={`connector-app-icon ${m.accent}`}><Icon size={17}/></span><span className={`connector-status ${c.status.toLowerCase()}`}>{c.status}</span></div><strong>{c.name}</strong><small>{m.label} · {c.direction.replace("BIDIRECTIONAL","TWO-WAY")}</small><div className="connector-card-health"><span><b>{c.mappings?.length||0}</b> mappings</span><span><b>{c.lastSyncAt?"Synced":"Not synced"}</b></span></div><div className="connector-card-meta"><span>{c.lastError?"Needs attention":"Ready"}</span><ChevronRight size={15}/></div></button>})}</div>}
  {showNew&&<NewConnector config={config} onClose={()=>setShowNew(false)} onCreated={async c=>{setShowNew(false);await load();await open(c)}}/>}
 </section>;
}

function NewConnector({config,onClose,onCreated}:{config:ApiConfig;onClose:()=>void;onCreated:(c:Connector)=>Promise<void>}){
 const appOrigin=typeof window!=="undefined"?(process.env.NEXT_PUBLIC_APP_URL||window.location.origin):"";
 const defaultRedirect=`${appOrigin}/api/v1/connectors/oauth/callback`;
 const [provider,setProvider]=useState("google-sheets");const [name,setName]=useState("");const [direction,setDirection]=useState("IMPORT");const [interval,setInterval]=useState(0);const [targetProjectId,setTargetProjectId]=useState("");const [projects,setProjects]=useState<Array<{id:string;name:string}>>([]);const [baseUrl,setBaseUrl]=useState("");const [authType,setAuthType]=useState("NONE");const [clientId,setClientId]=useState("");const [clientSecret,setClientSecret]=useState("");const [authorizeUrl,setAuthorizeUrl]=useState("");const [tokenUrl,setTokenUrl]=useState("");const [scopes,setScopes]=useState("");const [apiToken,setApiToken]=useState("");const [apiKeyName,setApiKeyName]=useState("X-API-Key");const [apiKeyLocation,setApiKeyLocation]=useState("header");const [apiKeyPrefix,setApiKeyPrefix]=useState("");const [bearerHeader,setBearerHeader]=useState("Authorization");const [bearerPrefix,setBearerPrefix]=useState("Bearer");const [customHeadersText,setCustomHeadersText]=useState("");const [customQueryText,setCustomQueryText]=useState("");const [username,setUsername]=useState("");const [password,setPassword]=useState("");const [prmsProjectId,setPrmsProjectId]=useState("");const [saving,setSaving]=useState(false); const [prmsStatus,setPrmsStatus]=useState<{configured:boolean;baseUrl:string;tokenUrl:string;missing:string[]}|null>(null);
 useEffect(()=>{if(provider==="prms")void connectorApi.prmsStatus(config).then(setPrmsStatus).catch(()=>setPrmsStatus(null));else setPrmsStatus(null)},[provider,config]);
 useEffect(()=>{setInterval(provider==="prms"?60:0)},[provider]);
 useEffect(()=>{void api.listProjects(config).then(ps=>setProjects(ps.map(p=>({id:p.id,name:p.name})))).catch(()=>setProjects([]))},[config]);
 useEffect(()=>{if(provider==="google-sheets"){setBaseUrl("https://sheets.googleapis.com/v4/");setAuthType("OAUTH2_AUTHORIZATION_CODE");setAuthorizeUrl("https://accounts.google.com/o/oauth2/v2/auth");setTokenUrl("https://oauth2.googleapis.com/token");setScopes("https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive.metadata.readonly");}else if(provider==="microsoft-365"){setBaseUrl("https://graph.microsoft.com/v1.0/");setAuthType("OAUTH2_AUTHORIZATION_CODE");setAuthorizeUrl("https://login.microsoftonline.com/common/oauth2/v2.0/authorize");setTokenUrl("https://login.microsoftonline.com/common/oauth2/v2.0/token");setScopes("User.Read Files.ReadWrite offline_access");}else if(provider==="prms"){setBaseUrl("https://prmscloud.com");setAuthType("NONE");setAuthorizeUrl("");setTokenUrl("");setScopes("");setPrmsProjectId("")}else{setBaseUrl("");setAuthType("BEARER");setAuthorizeUrl("");setTokenUrl("");setScopes("")}},[provider]);
 const firstClassOAuth=provider==="google-sheets"||provider==="microsoft-365";
 const customHeaderPairs=customHeadersText.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const i=line.indexOf(":");return i>0?[line.slice(0,i).trim(),line.slice(i+1).trim()] as const:null}).filter(Boolean) as Array<readonly [string,string]>;
 const customQueryPairs=customQueryText.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const i=line.indexOf("=");return i>0?[line.slice(0,i).trim(),line.slice(i+1).trim()] as const:null}).filter(Boolean) as Array<readonly [string,string]>;
 const credentialValid=authType==="NONE"||authType==="OAUTH2_CLIENT_CREDENTIALS"?(authType==="NONE"||Boolean(clientId.trim()&&clientSecret.trim()&&authorizeUrl.trim()&&tokenUrl.trim())):authType==="OAUTH2_AUTHORIZATION_CODE"?(firstClassOAuth||Boolean(clientId.trim()&&clientSecret.trim()&&authorizeUrl.trim()&&tokenUrl.trim())):authType==="BASIC"?Boolean(username.trim()&&password.trim()):authType==="API_KEY"?Boolean(apiToken.trim()&&apiKeyName.trim()):authType==="CUSTOM_HEADERS"?customHeaderPairs.length>0||customQueryPairs.length>0:Boolean(apiToken.trim());
 const valid=Boolean(name.trim()&&baseUrl.trim()&&credentialValid&&(provider!=="prms"||prmsProjectId.trim()));
 async function save(){if(!valid)return;setSaving(true);try{
   const oauth=authType.startsWith("OAUTH2")?{authorizeUrl,tokenUrl,clientId:clientId||undefined,redirectUri:defaultRedirect,scopes}:undefined;
   const auth:any={};
   if(authType==="API_KEY")auth.apiKey={name:apiKeyName.trim(),location:apiKeyLocation,prefix:apiKeyPrefix.trim()||undefined};
   if(authType==="BEARER")auth.bearer={header:bearerHeader.trim()||"Authorization",prefix:bearerPrefix.trim()};
   if(authType==="CUSTOM_HEADERS"){auth.customHeaderNames=customHeaderPairs.map(([k])=>k);auth.customQueryParamNames=customQueryPairs.map(([k])=>k);}
   let secrets:any=undefined;
   if(authType.startsWith("OAUTH2"))secrets=clientSecret?{clientSecret}:undefined;
   else if(authType==="API_KEY")secrets={apiKey:apiToken};
   else if(authType==="BASIC")secrets={username,password};
   else if(authType==="CUSTOM_HEADERS")secrets={customHeaders:Object.fromEntries(customHeaderPairs),customQueryParams:Object.fromEntries(customQueryPairs)};
   else if(authType==="BEARER")secrets={bearerToken:apiToken};
   const c=await connectorApi.create(config,{name:name.trim(),provider,baseUrl,authType,direction,config:{targetProjectId:targetProjectId||null,oauth,auth,prms:provider==="prms"?{projectId:prmsProjectId.trim()}:undefined,sync:{entities:["task"],conflict:"external_wins",intervalMinutes:interval},operations:{},response:{itemsPath:"",idField:"id"},google:provider==="google-sheets"?{headerRow:1}:undefined},secrets});
   notify({kind:"success",title:"Connection created",message:firstClassOAuth?"Connection created. Complete provider authorization, then choose the data source.":"Connection is ready. Discover the API, map its data and test before syncing."});await onCreated(c)
 }catch(e){notify({kind:"error",title:"Connection could not be created",message:e instanceof Error?e.message:"The connector could not be saved."})}finally{setSaving(false)}}
 const ProviderIcon=providerMeta[provider].icon;
 return <div className="connector-modal-backdrop"><div className="connector-modal connector-wizard-v2"><header><div><span className="eyebrow">NEW CONNECTION · STEP 1</span><h2>Connect an external system</h2><p>Choose a ready-made provider or connect almost any HTTP API. Authentication details stay encrypted and technical plumbing stays out of the way.</p></div><button className="icon-button" onClick={onClose}><X size={16}/></button></header>
  <div className="provider-picker">{Object.entries(providerMeta).map(([key,m]:any)=>{const Icon=m.icon;return <button key={key} className={provider===key?"selected":""} onClick={()=>setProvider(key)}><span className={`provider-icon ${m.accent}`}><Icon size={18}/></span><span><b>{m.label}</b><small>{m.sub}</small></span>{provider===key&&<Check size={16}/>}</button>})}</div>
  <div className="wizard-section"><div className="wizard-section-head"><span>Connection identity</span><small>Required</small></div><div className="wizard-grid"><label>Connection name<input value={name} onChange={e=>setName(e.target.value)} placeholder={provider==="google-sheets"?"Google Sheets · Project Schedule":provider==="microsoft-365"?"Microsoft 365 · Project Data":provider==="prms"?"PRMS · Project Data":"Production API"}/></label><label>Target SI project<select value={targetProjectId} onChange={e=>setTargetProjectId(e.target.value)}><option value="">Choose after connection</option>{projects.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label></div></div>
  {provider==="google-sheets"?<div className="wizard-account-card"><FileSpreadsheet size={22}/><div><b>Google Sheets</b><span>Connect the Google account once, then select the spreadsheet and worksheet. Google handles login and consent.</span></div><span className="wizard-badge">NATIVE</span></div>:provider==="microsoft-365"?<div className="wizard-account-card"><CloudCog size={22}/><div><b>Microsoft 365</b><span>Connect Microsoft once, then select Excel data through Microsoft Graph.</span></div><span className="wizard-badge">NATIVE</span></div>:provider==="prms"?<div className="wizard-section"><div className="wizard-section-head"><span>PRMS project</span><small>Only project identity is required</small></div><div className="wizard-grid"><label className="wide">Project ID<input value={prmsProjectId} onChange={e=>setPrmsProjectId(e.target.value.replace(/\s/g, ""))} placeholder="e.g. 12345" inputMode="numeric" autoComplete="off"/></label></div><div className="connector-callout"><ShieldCheck size={16}/><div><b>Platform-managed PRMS authentication</b><span>Schedule Intelligence securely calls the PRMS token endpoint with the server-side bootstrap Bearer token and ClientId/ClientSecret, extracts <code>accessToken</code>, then uses that token for PRMS project APIs.</span>{prmsStatus&&<small className={prmsStatus.configured?"prms-config-ready":"prms-config-missing"}>{prmsStatus.configured?`PRMS authentication is configured on the API server (${prmsStatus.baseUrl}). Token URL: ${prmsStatus.tokenUrl}`:`PRMS authentication is missing: ${prmsStatus.missing.join(", ")}. Token URL: ${prmsStatus.tokenUrl}. Add these variables to the environment used by Docker Compose.`}</small>}</div></div></div>:<div className="wizard-section"><div className="wizard-section-head"><span>Universal API</span><small>REST · OpenAPI · internal APIs</small></div><div className="wizard-grid"><label>Base URL<input value={baseUrl} onChange={e=>setBaseUrl(e.target.value)} placeholder="https://api.company.com/v1"/></label><label>Authentication<select value={authType} onChange={e=>setAuthType(e.target.value)}><option value="NONE">No authentication</option><option value="API_KEY">API key</option><option value="BEARER">Bearer token</option><option value="BASIC">Basic authentication</option><option value="CUSTOM_HEADERS">Custom headers / query</option><option value="OAUTH2_AUTHORIZATION_CODE">OAuth 2.0 Authorization Code</option><option value="OAUTH2_CLIENT_CREDENTIALS">OAuth 2.0 Client Credentials</option></select></label>
   {authType==="API_KEY"&&<><label>API key name<input value={apiKeyName} onChange={e=>setApiKeyName(e.target.value)} placeholder="X-API-Key"/></label><label>Send key in<select value={apiKeyLocation} onChange={e=>setApiKeyLocation(e.target.value)}><option value="header">Header</option><option value="query">Query parameter</option></select></label><label>Prefix (optional)<input value={apiKeyPrefix} onChange={e=>setApiKeyPrefix(e.target.value)} placeholder="Api-Key"/></label><label>API key<input type="password" value={apiToken} onChange={e=>setApiToken(e.target.value)} placeholder="Stored encrypted" autoComplete="new-password"/></label></>}
   {authType==="BEARER"&&<><label>Header name<input value={bearerHeader} onChange={e=>setBearerHeader(e.target.value)} placeholder="Authorization"/></label><label>Token prefix<input value={bearerPrefix} onChange={e=>setBearerPrefix(e.target.value)} placeholder="Bearer"/></label><label className="wide">Bearer token<input type="password" value={apiToken} onChange={e=>setApiToken(e.target.value)} placeholder="Stored encrypted" autoComplete="new-password"/></label></>}
   {authType==="BASIC"&&<><label>Username<input value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/></label></>}
   {authType==="CUSTOM_HEADERS"&&<><label className="wide">Secret headers<small>One per line: <code>X-Tenant-ID: secret-value</code></small><textarea value={customHeadersText} onChange={e=>setCustomHeadersText(e.target.value)} placeholder={'X-Tenant-ID: company-123\nX-API-Token: secret-value'} /></label><label className="wide">Secret query parameters<small>Optional. One per line: <code>tenant=company-123</code></small><textarea value={customQueryText} onChange={e=>setCustomQueryText(e.target.value)} placeholder={'tenant=company-123'} /></label></>}
   {authType.startsWith("OAUTH2")&&<><label>OAuth client ID<input value={clientId} onChange={e=>setClientId(e.target.value)} autoComplete="off"/></label><label>OAuth client secret<input type="password" value={clientSecret} onChange={e=>setClientSecret(e.target.value)} autoComplete="new-password"/></label><label>Authorize URL<input value={authorizeUrl} onChange={e=>setAuthorizeUrl(e.target.value)}/></label><label>Token URL<input value={tokenUrl} onChange={e=>setTokenUrl(e.target.value)}/></label><label className="wide">Scopes<input value={scopes} onChange={e=>setScopes(e.target.value)} placeholder="space-separated scopes"/></label></>}
  </div></div>}
  <div className="wizard-section"><div className="wizard-section-head"><span>Sync policy</span><small>Safe by default</small></div><div className="wizard-grid"><label>Data direction<select value={direction} onChange={e=>setDirection(e.target.value)}><option value="IMPORT">Import → SI</option><option value="BIDIRECTIONAL">Two-way · explicit write-back</option><option value="EXPORT">Export from SI</option></select></label><label>Automatic sync<select value={interval} onChange={e=>setInterval(Number(e.target.value))}><option value={0}>Manual only</option><option value={15}>Every 15 minutes</option><option value={30}>Every 30 minutes</option><option value={60}>Hourly</option><option value={1440}>Daily</option></select></label></div></div>
  <div className="connector-callout"><ShieldCheck size={16}/><div><b>Safe connection boundary</b><span>Credentials are encrypted. Reads can be discovered and mapped before any write operation is enabled. API keys can be sent in the header or query string when the provider requires it.</span></div></div>
  <footer><span className="wizard-validity">{valid?<><CheckCircle2 size={14}/> Ready to create</>:<>Complete the required connection fields</>}</span><div className="composer-actions"><button className="ghost-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={!valid||saving} onClick={()=>void save()}>{saving?<><RefreshCw className="spin" size={14}/> Creating…</>:<><Plus size={14}/> Create connection</>}</button></div></footer>
 </div></div>;
}

function ConnectorDetail({config,connector,onBack,onRefresh,onTest,onSync,busy,onDelete,tab,setTab,onOpenProject}:{config:ApiConfig;connector:Connector;onBack:()=>void;onRefresh:()=>Promise<void>;onTest:()=>void;onSync:()=>void;busy:boolean;onDelete:()=>void;tab:string;setTab:(v:string)=>void;onOpenProject?: (projectId:string)=>void}){
 const isGoogle=connector.provider==="google-sheets";const isMicrosoft=connector.provider==="microsoft-365";const isPrms=connector.provider==="prms";const isFirstClass=isGoogle||isMicrosoft;const isUniversal=!isFirstClass;
 const [webhook,setWebhook]=useState<string|null>(null);const [authorizing,setAuthorizing]=useState(false);const [credentialReady,setCredentialReady]=useState(false);
 async function authorize(){
  setAuthorizing(true);
  const popup=window.open("about:blank","si-oauth","width=720,height=760,resizable=yes,scrollbars=yes");
  try{
   if(!popup){notify({kind:"warning",title:"Authorization window was blocked",message:"Allow pop-ups for Schedule Intelligence and click Connect account again."});return;}
   const currentRedirect=`${window.location.origin}/api/v1/connectors/oauth/callback`;
   const oauth={...(connector.config?.oauth||{}),redirectUri:currentRedirect};
   await connectorApi.update(config,connector.id,{config:{...(connector.config||{}),oauth}});
   const r=await connectorApi.authorize(config,connector.id);
   popup.location.href=r.url;
   notify({kind:"info",title:`${isMicrosoft?"Microsoft":"Google"} authorization opened`,message:"Complete authorization in the provider window. Schedule Intelligence will refresh the connection automatically."});
  }catch{try{popup?.close()}catch{}}finally{setAuthorizing(false)}
 }
 async function addWebhook(){try{const r=await connectorApi.webhook(config,connector.id);const url=`${window.location.origin}/api/v1/connectors/webhooks/${r.token}`;setWebhook(url);await onRefresh();notify({kind:"success",title:"Webhook created",message:"The inbound endpoint is ready to receive external events."})}catch{}}
 const tabs=isPrms?["overview","schedule","webhooks"]:isFirstClass?["overview","data","mapping","sync","webhooks"]:["overview","discover","contract","mapping","sync","webhooks"];
 useEffect(()=>{void connectorApi.credential(config,connector.id).then(r=>setCredentialReady(Boolean(r.hasCredential))).catch(()=>setCredentialReady(false));},[config.baseUrl,connector.id,connector.status,connector.config]);
 useEffect(()=>{const handler=(e:MessageEvent)=>{if(e.origin!==window.location.origin)return;if(e.data?.type==="SI_OAUTH_COMPLETE"){notify({kind:"success",title:"Account connected",message:"OAuth authorization completed. The connector is refreshing its connection state."});void onRefresh()}else if(e.data?.type==="SI_OAUTH_ERROR"){notify({kind:"error",title:"Account connection failed",message:String(e.data?.message||"The OAuth provider did not authorize the connection.")});void onRefresh()}};window.addEventListener("message",handler);return()=>window.removeEventListener("message",handler)},[onRefresh]);
 return <section className="connector-hub connector-detail-v2"><button className="connector-back" onClick={onBack}><ArrowLeft size={14}/> All connections</button><header className="connector-detail-head"><div><span className="eyebrow">CONNECTION · {providerMeta[connector.provider]?.label||connector.provider}</span><h1>{connector.name}</h1><p>{connector.lastError||"Controlled integration boundary between the external system and Schedule Intelligence."}</p></div><div className="connector-detail-actions"><span className={`connector-status ${connector.status.toLowerCase()}`}>{connector.status}</span>{(isUniversal||isPrms)&&<button className="ghost-button" onClick={onTest} disabled={busy}><CheckCircle2 size={14}/> Test</button>}{!isPrms&&<button className="primary-button" onClick={onSync} disabled={busy||connector.direction==="EXPORT"}><RefreshCw className={busy?"spin":""} size={14}/> Sync now</button>}<button className="danger-button" onClick={onDelete}><Trash2 size={14}/></button></div></header><nav className="connector-tabs">{tabs.map(x=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav>
 {tab==="overview"&&<Overview config={config} connector={connector} onAuthorize={authorize} authorizing={authorizing} credentialReady={credentialReady} onWebhook={addWebhook} webhook={webhook} onRefresh={onRefresh}/>} 
 {tab==="data"&&isGoogle&&<GoogleSheetsBrowser config={config} connector={connector} onRefresh={onRefresh}/>} {tab==="data"&&isMicrosoft&&<MicrosoftExcelBrowser config={config} connector={connector} onRefresh={onRefresh}/>} {tab==="schedule"&&isPrms&&<PrmsSchedulePanel config={config} connector={connector} onOpenProject={onOpenProject}/>} 
 {tab==="discover"&&isUniversal&&<UniversalDiscovery config={config} connector={connector} onRefresh={onRefresh}/>} 
 {tab==="contract"&&isUniversal&&<ContractBuilder config={config} connector={connector} onRefresh={onRefresh}/>} 
 {tab==="mapping"&&<MappingStudio config={config} connector={connector} onRefresh={onRefresh}/>} 
 {tab==="sync"&&<SyncRuns config={config} id={connector.id}/>} 
 {tab==="webhooks"&&<WebhookStudio config={config} connector={connector} webhook={webhook} onWebhook={addWebhook}/>} 
 </section>;
}


function PrmsSchedulePanel({config,connector,onOpenProject}:{config:ApiConfig;connector:Connector;onOpenProject?:(projectId:string)=>void}){
 const [data,setData]=useState<any>(null); const [loading,setLoading]=useState(false); const [error,setError]=useState("");
 const projectId=String(connector.config?.prms?.projectId||"");
 async function load(){setLoading(true);setError("");try{setData(await connectorApi.prmsSchedule(config,connector.id))}catch(e){setError(e instanceof Error?e.message:"Unable to load PRMS schedule.")}finally{setLoading(false)}}
 useEffect(()=>{void load()},[connector.id,config.baseUrl]);
 const tasks=Array.isArray(data?.tasks)?data.tasks:[];
 return <div className="connector-panel prms-schedule-panel"><div className="panel-title"><div><span className="studio-kicker">PRMS LIVE SCHEDULE</span><h2>Project {projectId||"—"}</h2><p>Schedule Intelligence reads actual and expected dates from PRMS. Expected dates can be written back; actual dates remain source-owned.</p></div><div className="prms-schedule-actions"><button className="ghost-button" onClick={()=>void load()} disabled={loading}><RefreshCw className={loading?"spin":""} size={13}/> {loading?"Loading…":"Refresh"}</button><button className="primary-button" onClick={async()=>{setLoading(true);try{const r=await connectorApi.prmsOpenGantt(config,connector.id);notify({kind:"success",title:"PRMS schedule opened",message:`Loaded ${r.taskCount} schedule items into the Gantt.`});onOpenProject?.(r.projectId)}catch(e){setError(e instanceof Error?e.message:"Unable to open the PRMS schedule in Gantt.")}finally{setLoading(false)}}} disabled={loading}><Sparkles size={13}/> Open in Gantt</button></div></div>{error&&<div className="connector-error-detail"><CircleAlert size={14}/><span>{error}</span></div>}{data&&<><div className="prms-preview-stats"><span>{data.eventCount||0} events</span><span>{data.actionCount||0} actions</span><span>{data.taskCount||0} schedule items</span><span>Expected · read/write</span><span>Actual · read-only</span><span>Auto-sync · hourly minimum</span></div><div className="prms-preview-list">{tasks.slice(0,100).map((t:any)=><div className="prms-preview-row" key={t.id}><strong title={t.name}>{t.name}</strong><span>Expected {t.expectedStart?.slice(0,10)||"—"} → {t.expectedEnd?.slice(0,10)||"—"}</span><span>Actual {t.actualStart?.slice(0,10)||"—"} → {t.actualEnd?.slice(0,10)||"ongoing"}</span></div>)}{tasks.length>100&&<div className="prms-preview-row"><span>Showing first 100 items for a safe preview.</span></div>}</div></>}</div>
}

function OAuthSetup({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){
 const oauth=connector.config?.oauth||{};
 const [clientId,setClientId]=useState(String(oauth.clientId||""));
 const [clientSecret,setClientSecret]=useState("");
 const [saving,setSaving]=useState(false);
 const redirect=typeof window!=="undefined"?`${window.location.origin}/api/v1/connectors/oauth/callback`:String(oauth.redirectUri||"");
 const provider=connector.provider==="microsoft-365"?"Microsoft 365":"Google Sheets";
 async function save(){setSaving(true);try{const nextOauth={...oauth,clientId:clientId.trim(),redirectUri:redirect};const body:any={config:{...(connector.config||{}),oauth:nextOauth}};if(clientSecret.trim())body.secrets={clientSecret:clientSecret.trim()};await connectorApi.update(config,connector.id,body);await onRefresh();notify({kind:"success",title:"OAuth setup saved",message:`${provider} OAuth configuration is ready. Use Connect account to authorize.`});setClientSecret("")}catch{}finally{setSaving(false)}}
 return <div className="oauth-provider-setup"><div className="oauth-setup-head"><div><b>Provider OAuth setup</b><small>{provider} uses Authorization Code OAuth. The client secret is stored encrypted and is never returned to the browser after save.</small></div><span className={clientId.trim()&&oauth.redirectUri?"ready":"needs-setup"}>{clientId.trim()&&oauth.redirectUri?"READY":"SETUP REQUIRED"}</span></div><div className="oauth-setup-grid"><label>OAuth Client ID<input value={clientId} onChange={e=>setClientId(e.target.value)} placeholder={connector.provider==="google-sheets"?"1234567890-....apps.googleusercontent.com":"Application (client) ID"} autoComplete="off"/></label><label>OAuth Client Secret<input type="password" value={clientSecret} onChange={e=>setClientSecret(e.target.value)} placeholder={oauth.hasClientSecret?"Saved — enter only to replace":"Client secret"} autoComplete="new-password"/></label><label className="wide">Exact Authorized Redirect URI<input value={redirect} readOnly onFocus={e=>e.currentTarget.select()}/><small>Register this exact URI in the provider console. Do not change localhost to 127.0.0.1 (or vice versa).</small></label></div><div className="oauth-setup-actions"><button className="ghost-button" onClick={()=>navigator.clipboard?.writeText(redirect).then(()=>notify({kind:"success",title:"Redirect URI copied",message:"Paste the exact URI into the provider OAuth client."}))}><Copy size={13}/> Copy redirect URI</button><button className="primary-button" disabled={saving||!clientId.trim()||!redirect} onClick={()=>void save()}>{saving?<><RefreshCw className="spin" size={13}/> Saving…</>:<><Save size={13}/> Save OAuth setup</>}</button></div></div>
}

function Overview({config,connector,onAuthorize,authorizing,credentialReady,onWebhook,webhook,onRefresh}:{config:ApiConfig;connector:Connector;onAuthorize:()=>Promise<void>;authorizing:boolean;credentialReady:boolean;onWebhook:()=>Promise<void>;webhook:string|null;onRefresh:()=>Promise<void>}){return <div className="connector-detail-grid connector-overview-grid"><div className="connector-panel connector-connection-card"><div className="studio-kicker">ACCOUNT / CREDENTIAL</div><h3><KeyRound size={15}/> {connector.authType.replaceAll("_"," ")}</h3><p>{connector.provider==="google-sheets"?"Connect the Google account that owns or can access the spreadsheets. Google handles login and consent in its own window.":connector.provider==="microsoft-365"?"Connect the Microsoft account that can access the Excel workbooks. Microsoft handles login and consent in its own window.":connector.provider==="prms"?"PRMS uses a server-side token exchange. The bootstrap bearer token, ClientId and ClientSecret remain on the API server; only the resulting access token is used for the configured PRMS endpoint.":"Credentials are encrypted at rest and injected only at request time."}</p>{connector.authType.startsWith("OAUTH2")&&<OAuthSetup config={config} connector={connector} onRefresh={onRefresh}/>} {connector.authType.startsWith("OAUTH2")&&<button className="primary-button" onClick={()=>void onAuthorize()} disabled={authorizing||!connector.config?.oauth?.clientId||!connector.config?.oauth?.redirectUri||!credentialReady}><KeyRound size={14}/> {authorizing?"Opening…":connector.status==="CONNECTED"?"Re-authorize account":credentialReady?"Connect account":"Save client secret first"}</button>}<div className="connection-facts">{connector.provider==="prms"&&<span><b>Project ID</b>{connector.config?.prms?.projectId||"Not configured"}</span>}<span><b>Direction</b>{connector.direction.replace("BIDIRECTIONAL","TWO-WAY")}</span><span><b>Target</b>{connector.config?.targetProjectId?"Project selected":"Choose during setup"}</span><span><b>Last sync</b>{connector.lastSyncAt?new Date(connector.lastSyncAt).toLocaleString():"Never"}</span></div></div><div className="connector-panel"><div className="studio-kicker">INTELLIGENCE BOUNDARY</div><h3><ShieldCheck size={15}/> Controlled data contract</h3><p>External fields stay external until you map them. SI owns scheduling intelligence such as dependencies, critical path, slack, forecast and resource pressure.</p><div className="boundary-flow"><span>External schema</span><ChevronRight/><span>Mapping + transform</span><ChevronRight/><span>SI canonical model</span></div><div className="boundary-rules"><span><Check size={13}/> No inferred writes</span><span><Check size={13}/> Identity preserved</span><span><Check size={13}/> Failed records visible</span></div></div><div className="connector-panel connector-health-card"><div className="studio-kicker">HEALTH</div><div className="health-orbit"><div><b>{connector.status==="CONNECTED"?"READY":"ATTENTION"}</b><span>{connector.lastError?"Fix the signal below":"Connection boundary is healthy"}</span></div><span className={`health-dot ${connector.status.toLowerCase()}`}/></div>{connector.lastError&&<div className="connector-error-detail"><CircleAlert size={14}/><span>{connector.lastError}</span></div>}</div></div>}

function UniversalDiscovery({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){const [specUrl,setSpecUrl]=useState("");const [operationKey,setOperationKey]=useState("");const [result,setResult]=useState<any>(null);const [params,setParams]=useState("{}");const operations=connector.config?.operations||{};useEffect(()=>{const first=Object.keys(operations).find(k=>operations[k]?.method==="GET")||Object.keys(operations)[0];if(first)setOperationKey(first)},[connector.id]);async function importSpec(){try{const r=await connectorApi.importOpenApi(config,connector.id,{specUrl});notify({kind:"success",title:"API contract imported",message:`Discovered ${r.operationCount} operations from ${r.title}.`});await onRefresh()}catch{}}async function discover(){try{const body=JSON.parse(params||"{}");const r=await connectorApi.discover(config,connector.id,operationKey,{body});setResult(r);notify({kind:"success",title:"Operation discovered",message:`Received ${r.recordCount} records and detected ${r.fields.length} fields.`})}catch{}}return <div className="connector-panel discovery-studio"><div className="studio-section-title"><div><span className="studio-kicker">UNIVERSAL DISCOVERY</span><h2>Turn an unknown API into a visible data contract</h2><p>Paste an OpenAPI JSON URL, import the contract, then test a read operation and use its real response as the mapping source.</p></div></div><div className="discovery-import"><input value={specUrl} onChange={e=>setSpecUrl(e.target.value)} placeholder="https://api.company.com/openapi.json"/><button className="primary-button" disabled={!specUrl.trim()} onClick={()=>void importSpec()}><Database size={14}/> Import OpenAPI</button></div><div className="discovery-divider"><span>OR DISCOVER A CONFIGURED OPERATION</span></div><div className="discovery-run"><select value={operationKey} onChange={e=>setOperationKey(e.target.value)}><option value="">Select operation</option>{Object.entries<any>(operations).map(([k,v])=><option key={k} value={k}>{v.method} · {v.path} · {v.summary||k}</option>)}</select><input value={params} onChange={e=>setParams(e.target.value)} placeholder='Path/body values JSON, e.g. {"id":"123"}'/><button className="primary-button" disabled={!operationKey} onClick={()=>void discover()}><Play size={14}/> Discover data</button></div>{result&&<div className="discovery-result"><div className="discovery-result-head"><span className="connector-status connected">SUCCESS</span><b>{result.method} {result.path}</b><span>{result.recordCount} records</span><span>{result.fields.length} fields</span></div><div className="discovery-fields">{result.fields.map((f:string)=><code key={f}>{f}</code>)}</div><pre>{JSON.stringify(result.sample?.[0]??result.sample??{},null,2)}</pre></div>}</div>}

function ContractBuilder({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){const [ops,setOps]=useState<any>(connector.config?.operations||{});const [selectedOp,setSelectedOp]=useState("taskList");const [queryText,setQueryText]=useState("");const [headersText,setHeadersText]=useState("");const [bodyText,setBodyText]=useState("");useEffect(()=>{setOps(connector.config?.operations||{})},[connector.id,connector.config]);useEffect(()=>{const op=ops[selectedOp]||{};setQueryText(JSON.stringify(op.query||{},null,2));setHeadersText(JSON.stringify(op.headers||{},null,2));setBodyText(op.bodyTemplate===undefined?"":JSON.stringify(op.bodyTemplate,null,2))},[selectedOp,ops]);async function save(){try{await connectorApi.update(config,connector.id,{config:{...connector.config,operations:ops}});notify({kind:"success",title:"API contract saved",message:"The connector now has an explicit operation contract."});await onRefresh()}catch{}}const setField=(k:string,f:string,v:any)=>setOps((x:any)=>({...x,[k]:{method:x[k]?.method||"GET",path:x[k]?.path||"",enabled:x[k]?.enabled!==false,...x[k],[f]:v}}));const saveAdvanced=()=>{try{const query=queryText.trim()?JSON.parse(queryText):undefined;const headers=headersText.trim()?JSON.parse(headersText):undefined;const body=bodyText.trim()?JSON.parse(bodyText):undefined;setOps((x:any)=>({...x,[selectedOp]:{...x[selectedOp],query,headers,bodyTemplate:body}}));notify({kind:"success",title:"Request settings staged",message:"Advanced request settings are ready to be saved with the API contract."})}catch{notify({kind:"warning",title:"Invalid request JSON",message:"Query, headers and body template must be valid JSON objects."})}};return <div className="connector-panel contract-studio"><div className="studio-section-title"><div><span className="studio-kicker">OPERATION CONTRACT</span><h2>Only expose what the external system is allowed to do</h2><p>Use the simple contract table for normal APIs. Advanced request settings are available when an API needs extra query parameters, headers or a body template.</p></div><button className="primary-button" onClick={()=>void save()}><Save size={14}/> Save contract</button></div><div className="contract-table"><div className="contract-table-head"><span>Capability</span><span>Method</span><span>Path</span><span>State</span></div>{[["projectList","Projects · list"],["taskList","Tasks · list"],["resourceList","Resources · list"],["projectCreate","Projects · create"],["projectUpdate","Projects · update"],["taskCreate","Tasks · create"],["taskUpdate","Tasks · update"],["taskDelete","Tasks · delete"]].map(([key,label])=><div className="contract-row" key={key}><b>{label}</b><select value={ops[key]?.method||(/Create/.test(key)?"POST":/Update|Delete/.test(key)?"PATCH":"GET")} onChange={e=>setField(key,"method",e.target.value)}><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select><input value={ops[key]?.path||""} onChange={e=>setField(key,"path",e.target.value)} placeholder={key.includes("List")?"/tasks":key.includes("Delete")?"/tasks/{id}":"/tasks"}/><label><input type="checkbox" checked={Boolean(ops[key]?.path)&&ops[key]?.enabled!==false} onChange={e=>setField(key,"enabled",e.target.checked)}/><span>{ops[key]?.enabled!==false&&ops[key]?.path?"Enabled":"Off"}</span></label></div>)}</div><div className="contract-advanced"><div className="contract-advanced-head"><div><span className="studio-kicker">ADVANCED REQUEST</span><h3>Provider-specific details</h3><p>Values here are non-secret request settings. Secrets belong in the encrypted connection credentials.</p></div><select value={selectedOp} onChange={e=>setSelectedOp(e.target.value)}>{["projectList","taskList","resourceList","projectCreate","projectUpdate","taskList","taskCreate","taskUpdate","taskDelete"].filter((x,i,a)=>a.indexOf(x)===i).map(k=><option key={k} value={k}>{k}</option>)}</select></div><div className="contract-advanced-grid"><label>Query parameters<small>JSON object</small><textarea value={queryText} onChange={e=>setQueryText(e.target.value)} placeholder={'{\n  "workspace": "123"\n}'}/></label><label>Request headers<small>JSON object · do not paste secrets</small><textarea value={headersText} onChange={e=>setHeadersText(e.target.value)} placeholder={'{\n  "X-Version": "2026-01"\n}'}/></label><label className="wide">Body template<small>JSON · used for POST / PUT / PATCH when no runtime body is supplied</small><textarea value={bodyText} onChange={e=>setBodyText(e.target.value)} placeholder={'{\n  "status": "active"\n}'}/></label></div><button className="ghost-button" onClick={saveAdvanced}><Save size={13}/> Apply request settings</button></div><div className="connector-callout"><CircleAlert size={16}/><div><b>Write gate</b><span>A write endpoint becomes usable only after it exists, is enabled, has a field mapping and passes a real test request.</span></div></div></div>}

function MappingStudio({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){const [entity,setEntity]=useState("task");const [rows,setRows]=useState<any[]>([]);const existing=connector.mappings||[];useEffect(()=>setRows(existing.filter(m=>m.entityType===entity).map(m=>({...m}))),[connector.id,connector.mappings,entity]);async function add(){const external=prompt("External field name (for example Member_Name)");if(!external)return;const internal=prompt(`SI field for ${external}`,fieldHints[entity][0]);if(!internal)return;try{await connectorApi.addMapping(config,connector.id,{entityType:entity,externalField:external,internalField:internal,direction:"IMPORT",transform:{},required:false});await onRefresh();notify({kind:"success",title:"Field mapped",message:`${external} is now mapped to ${internal}.`})}catch{}}async function remove(id:string){try{await connectorApi.removeMapping(config,connector.id,id);await onRefresh()}catch{}}return <div className="connector-panel mapping-studio"><div className="studio-section-title"><div><span className="studio-kicker">DATA CONTRACT</span><h2>Map only what SI should understand</h2><p>External applications can have hundreds of fields. SI only needs the fields required for scheduling and resource intelligence.</p></div><div className="mapping-entity-switch">{entities.map(e=><button key={e} className={entity===e?"active":""} onClick={()=>setEntity(e)}>{e}</button>)}</div></div><div className="mapping-smart-grid"><div className="mapping-smart-card"><Sparkles size={16}/><div><b>Suggested canonical fields</b><span>{fieldHints[entity].join(" · ")}</span></div></div><button className="primary-button" onClick={()=>void add()}><Plus size={14}/> Add mapping</button></div><div className="mapping-list mapping-list-v2">{rows.length?rows.map(m=><div className="mapping-row-v2" key={m.id}><span className="mapping-external">{m.externalField}</span><ChevronRight size={14}/><span className="mapping-internal">{m.internalField}</span><select value={m.direction} onChange={async e=>{try{await connectorApi.updateMapping(config,connector.id,m.id,{direction:e.target.value});await onRefresh()}catch{}}}><option>IMPORT</option><option>BOTH</option><option>EXPORT</option></select><button onClick={()=>void remove(m.id)} aria-label={`Remove ${m.externalField}`}><Trash2 size={13}/></button></div>):<div className="connector-empty small"><p>No mappings yet. Start with identity, name, start and end for tasks.</p></div>}</div></div>}

function WebhookStudio({config,connector,webhook,onWebhook}:{config:ApiConfig;connector:Connector;webhook:string|null;onWebhook:()=>Promise<void>}){return <div className="connector-panel webhook-studio"><div className="studio-section-title"><div><span className="studio-kicker">EVENT CHANNEL</span><h2>Let external systems push changes into SI</h2><p>Polling is useful for state. Webhooks are the faster event path when the external application supports them.</p></div><button className="primary-button" onClick={()=>void onWebhook()}><Webhook size={14}/> Create inbound webhook</button></div>{webhook&&<div className="connector-webhook connector-webhook-v2"><code>{webhook}</code><button onClick={()=>void navigator.clipboard.writeText(webhook)}><Copy size={13}/> Copy</button></div>}<div className="webhook-contract"><span><b>Secure endpoint</b>Unique tokenized URL</span><span><b>Replay-safe foundation</b>Every delivery is recorded</span><span><b>No blind writes</b>Inbound data still passes mapping rules</span></div></div>}

function GoogleSheetsBrowser({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){const [query,setQuery]=useState("");const [files,setFiles]=useState<any[]>([]);const [loading,setLoading]=useState(false);const [spreadsheet,setSpreadsheet]=useState<any>(null);const [range,setRange]=useState("");const [values,setValues]=useState<string[][]>([]);const [selectedFile,setSelectedFile]=useState<any>(null);const [selectedSheet,setSelectedSheet]=useState("");const [headerRow,setHeaderRow]=useState(1);const [saving,setSaving]=useState(false);async function loadFiles(){setLoading(true);try{const r=await connectorApi.googleSpreadsheets(config,connector.id,query);setFiles(r.files||[])}catch{}finally{setLoading(false)}}async function chooseFile(file:any){setSelectedFile(file);try{const r=await connectorApi.googleSpreadsheet(config,connector.id,file.id);setSpreadsheet(r);const first=r.sheets?.[0]?.properties?.title||"";setSelectedSheet(first);setRange(first?`${first}!A1:Z30`:"")}catch{}}async function preview(){if(!selectedFile||!range.trim())return;setLoading(true);try{const r=await connectorApi.googleValues(config,connector.id,selectedFile.id,range.trim());setValues(r.values||[])}catch{}finally{setLoading(false)}}async function saveSelection(){if(!selectedFile||!selectedSheet)return;setSaving(true);try{const next={...(connector.config||{}),targetProjectId:connector.config?.targetProjectId||null,google:{...(connector.config?.google||{}),spreadsheetId:selectedFile.id,spreadsheetName:selectedFile.name,sheetTitle:selectedSheet,headerRow,range}};await connectorApi.update(config,connector.id,{config:next});await onRefresh();notify({kind:"success",title:"Data source selected",message:`${selectedFile.name} · ${selectedSheet} is now the active external dataset.`})}catch{}finally{setSaving(false)}}const headers=values[headerRow-1]||[];const sampleRows=values.slice(headerRow).slice(0,10);return <div className="connector-google connector-google-v2"><div className="google-journey"><div className="journey-step active"><b>1</b><span>Connect</span></div><ChevronRight/><div className="journey-step active"><b>2</b><span>Discover</span></div><ChevronRight/><div className="journey-step active"><b>3</b><span>Preview</span></div><ChevronRight/><div className={`journey-step ${headers.length?"active":""}`}><b>4</b><span>Map</span></div><ChevronRight/><div className="journey-step"><b>5</b><span>Sync</span></div></div><div className="connector-google-layout"><div className="connector-panel"><div className="panel-title"><div><span className="studio-kicker">GOOGLE ACCOUNT DATA</span><h3><FileSpreadsheet size={15}/> Choose spreadsheet</h3><p>Browse the files available to the connected Google account. No spreadsheet ID required.</p></div><button className="ghost-button" onClick={()=>void loadFiles()} disabled={loading}><RefreshCw size={14}/> Refresh</button></div><div className="google-search"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void loadFiles()}} placeholder="Search your spreadsheets…"/><button className="primary-button" onClick={()=>void loadFiles()} disabled={loading}><Search size={14}/> Find</button></div><div className="google-file-list">{files.length?files.map(f=><button key={f.id} className={`google-file ${selectedFile?.id===f.id?"active":""}`} onClick={()=>void chooseFile(f)}><FileSpreadsheet size={16}/><span><b>{f.name}</b><small>{f.modifiedTime?new Date(f.modifiedTime).toLocaleString():"Google Sheet"}</small></span><ChevronRight size={14}/></button>):<div className="connector-empty small"><p>{loading?"Loading spreadsheets…":"Search to discover spreadsheets."}</p></div>}</div></div><div className="connector-panel"><span className="studio-kicker">DATA PREVIEW</span><h3>Worksheet and live rows</h3>{!spreadsheet?<p>Select a spreadsheet to discover its worksheets.</p>:<><label className="google-field">Worksheet<select value={selectedSheet} onChange={e=>{const v=e.target.value;setSelectedSheet(v);setRange(`${v}!A1:Z30`)}}>{spreadsheet.sheets?.map((s:any)=><option key={s.properties.sheetId}>{s.properties.title}</option>)}</select></label><label className="google-field">Range<input value={range} onChange={e=>setRange(e.target.value)} placeholder="Sheet1!A1:Z30"/></label><label className="google-field">Header row<input type="number" min={1} value={headerRow} onChange={e=>setHeaderRow(Math.max(1,Number(e.target.value)||1))}/></label><div className="google-actions"><button className="ghost-button" onClick={()=>void preview()} disabled={loading}><Play size={14}/> Preview rows</button><button className="primary-button" onClick={()=>void saveSelection()} disabled={saving}><Save size={14}/> Save dataset</button></div>{values.length>0&&<div className="google-table-wrap"><table className="google-table"><thead><tr>{headers.map((h,i)=><th key={i}>{h||`Column ${i+1}`}</th>)}</tr></thead><tbody>{sampleRows.map((row,ri)=><tr key={ri}>{headers.map((_,i)=><td key={i}>{row?.[i]||""}</td>)}</tr>)}</tbody></table></div>}</>}</div></div>{headers.length>0&&<GoogleHeaderMapper config={config} connector={connector} headers={headers} onRefresh={onRefresh}/>}</div>}

function MicrosoftExcelBrowser({config,connector,onRefresh}:{config:ApiConfig;connector:Connector;onRefresh:()=>Promise<void>}){const [query,setQuery]=useState("");const [files,setFiles]=useState<any[]>([]);const [loading,setLoading]=useState(false);const [workbook,setWorkbook]=useState<any>(null);const [values,setValues]=useState<any[][]>([]);const [selectedFile,setSelectedFile]=useState<any>(null);const [selectedSheet,setSelectedSheet]=useState("");const [address,setAddress]=useState("A1:Z30");const [saving,setSaving]=useState(false);async function loadFiles(){setLoading(true);try{const r=await connectorApi.microsoftWorkbooks(config,connector.id,query);setFiles(r.files||[])}catch{}finally{setLoading(false)}}async function chooseFile(file:any){setSelectedFile(file);try{const r=await connectorApi.microsoftWorkbook(config,connector.id,file.id);setWorkbook(r);setSelectedSheet(r.sheets?.[0]?.id||"")}catch{}}async function preview(){if(!selectedFile||!selectedSheet)return;setLoading(true);try{const r=await connectorApi.microsoftValues(config,connector.id,selectedFile.id,selectedSheet,address);setValues(r.values||r.text||[])}catch{}finally{setLoading(false)}}async function saveSelection(){if(!selectedFile||!selectedSheet)return;setSaving(true);try{const next={...(connector.config||{}),microsoft:{...(connector.config?.microsoft||{}),itemId:selectedFile.id,itemName:selectedFile.name,sheetId:selectedSheet,address}};await connectorApi.update(config,connector.id,{config:next});await onRefresh();notify({kind:"success",title:"Excel dataset selected",message:`${selectedFile.name} is now the active Microsoft 365 dataset.`})}catch{}finally{setSaving(false)}}const headers=(values[0]||[]).map((v:any)=>String(v??""));const rows=values.slice(1,11);return <div className="connector-google connector-google-v2"><div className="google-journey"><div className="journey-step active"><b>1</b><span>Connect</span></div><ChevronRight/><div className="journey-step active"><b>2</b><span>Discover</span></div><ChevronRight/><div className="journey-step active"><b>3</b><span>Preview</span></div><ChevronRight/><div className={`journey-step ${headers.length?"active":""}`}><b>4</b><span>Map</span></div><ChevronRight/><div className="journey-step"><b>5</b><span>Sync</span></div></div><div className="connector-google-layout"><div className="connector-panel"><div className="panel-title"><div><span className="studio-kicker">MICROSOFT 365 DATA</span><h3><CloudCog size={15}/> Choose Excel workbook</h3><p>Browse .xlsx files visible to the connected Microsoft account.</p></div><button className="ghost-button" onClick={()=>void loadFiles()} disabled={loading}><RefreshCw size={14}/> Refresh</button></div><div className="google-search"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")void loadFiles()}} placeholder="Search Excel workbooks…"/><button className="primary-button" onClick={()=>void loadFiles()} disabled={loading}><Search size={14}/> Find</button></div><div className="google-file-list">{files.length?files.map(f=><button key={f.id} className={`google-file ${selectedFile?.id===f.id?"active":""}`} onClick={()=>void chooseFile(f)}><CloudCog size={16}/><span><b>{f.name}</b><small>{f.lastModifiedDateTime?new Date(f.lastModifiedDateTime).toLocaleString():"Excel workbook"}</small></span><ChevronRight size={14}/></button>):<div className="connector-empty small"><p>{loading?"Loading workbooks…":"Search to discover Excel workbooks."}</p></div>}</div></div><div className="connector-panel"><span className="studio-kicker">WORKBOOK PREVIEW</span><h3>Worksheet and live cells</h3>{!workbook?<p>Select an Excel workbook to discover its worksheets.</p>:<><label className="google-field">Worksheet<select value={selectedSheet} onChange={e=>setSelectedSheet(e.target.value)}>{workbook.sheets?.map((s:any)=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="google-field">Range address<input value={address} onChange={e=>setAddress(e.target.value)} placeholder="A1:Z30"/></label><div className="google-actions"><button className="ghost-button" onClick={()=>void preview()} disabled={loading}><Play size={14}/> Preview cells</button><button className="primary-button" onClick={()=>void saveSelection()} disabled={saving}><Save size={14}/> Save dataset</button></div>{values.length>0&&<div className="google-table-wrap"><table className="google-table"><thead><tr>{headers.map((h:string,i:number)=><th key={i}>{h||`Column ${i+1}`}</th>)}</tr></thead><tbody>{rows.map((row:any[],ri:number)=><tr key={ri}>{headers.map((_:string,i:number)=><td key={i}>{row?.[i]??""}</td>)}</tr>)}</tbody></table></div>}</>}</div></div>{headers.length>0&&<GoogleHeaderMapper config={config} connector={connector} headers={headers} onRefresh={onRefresh}/>}</div>}
function GoogleHeaderMapper({config,connector,headers,onRefresh}:{config:ApiConfig;connector:Connector;headers:string[];onRefresh:()=>Promise<void>}){const existing=connector.mappings||[];const [rows,setRows]=useState(headers.map(h=>{const e=existing.find(m=>m.externalField===h&&m.entityType==="task");const lower=h.toLowerCase();const suggestion=lower.includes("id_task")||lower==="id"?"externalId":lower.includes("task")||lower.includes("name")?"name":lower.includes("start")?"expectedStart":lower.includes("end")?"expectedEnd":lower.includes("status")?"status":lower.includes("progress")?"progressPct":lower.includes("member")?"resourceExternalId":"";return {externalField:h,internalField:e?.internalField||suggestion,direction:e?.direction||"IMPORT"}}));const [saving,setSaving]=useState(false);async function save(){setSaving(true);try{for(const r of rows.filter(x=>x.internalField)){const existingRow=existing.find(m=>m.externalField===r.externalField&&m.entityType==="task");if(existingRow)await connectorApi.updateMapping(config,connector.id,existingRow.id,{internalField:r.internalField,direction:r.direction});else await connectorApi.addMapping(config,connector.id,{entityType:"task",externalField:r.externalField,internalField:r.internalField,direction:r.direction,transform:{},required:["externalId","name","expectedStart","expectedEnd"].includes(r.internalField)})}await onRefresh();notify({kind:"success",title:"Mapping contract saved",message:"The detected columns are now mapped to Schedule Intelligence."})}catch{}finally{setSaving(false)}}return <div className="connector-panel google-mapper google-mapper-v2"><div className="panel-title"><div><span className="studio-kicker">STEP 4 · MAP</span><h3>Turn spreadsheet columns into scheduling meaning</h3><p>Suggestions are only suggestions. You remain in control of what enters SI and what can ever be written back.</p></div><button className="primary-button" onClick={()=>void save()} disabled={saving}><Save size={14}/> Save mapping</button></div><div className="google-map-grid">{rows.map((r,i)=><div className="google-map-row" key={`${r.externalField}-${i}`}><span className="google-header-chip">{r.externalField||`Column ${i+1}`}</span><ChevronRight size={14}/><select value={r.internalField} onChange={e=>setRows(x=>x.map((a,j)=>j===i?{...a,internalField:e.target.value}:a))}><option value="">Do not map</option>{fieldHints.task.map((f:string)=><option key={f}>{f}</option>)}</select><select value={r.direction} onChange={e=>setRows(x=>x.map((a,j)=>j===i?{...a,direction:e.target.value}:a))}><option>IMPORT</option><option>BOTH</option><option>EXPORT</option></select></div>)}</div></div>}
function SyncRuns({config,id}:{config:ApiConfig;id:string}){const[runs,setRuns]=useState<any[]>([]);const[loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);void connectorApi.runs(config,id).then(setRuns).catch(()=>setRuns([])).finally(()=>setLoading(false))},[config.baseUrl,id]);return <div className="connector-panel sync-studio"><div className="studio-section-title"><div><span className="studio-kicker">OBSERVE</span><h2>Synchronization history</h2><p>Every run has a result. Failures remain visible with record counts and error context.</p></div></div>{loading?<div className="connector-loading"><RefreshCw className="spin" size={18}/><span>Loading sync history…</span></div>:runs.length? <div className="sync-runs">{runs.map(r=><div className="sync-run sync-run-v2" key={r.id}><span className={`connector-status ${String(r.status).toLowerCase()}`}>{r.status}</span><b>{new Date(r.startedAt).toLocaleString()}</b><span>read <strong>{r.recordsRead}</strong></span><span>created <strong>{r.recordsCreated}</strong></span><span>updated <strong>{r.recordsUpdated}</strong></span><span>failed <strong className={r.recordsFailed?"danger":""}>{r.recordsFailed}</strong></span>{r.error&&<small>{r.error}</small>}</div>)}</div>:<div className="connector-empty small"><p>No sync runs yet. Run a controlled test after the mapping contract is ready.</p></div>}</div>}
